package io.github.nannxi.epaper;
import java.util.Arrays;
/** Exact 1-bit Oswald glyphs shared with the MCU; SIL OFL 1.1. */
public final class ClockPreview {
 private ClockPreview() {}
 private static final String HEX="";
 public static int[] pixels(int hour,int minute) {
  int[] p=new int[212*104];Arrays.fill(p,0xffffffff);
  int[] digits={hour/10,hour%10,minute/10,minute%10},xs={5,53,115,163};
  for(int g=0;g<4;g++)for(int y=0;y<88;y++)for(int x=0;x<44;x++) {
   int offset=(digits[g]*528+y*6+x/8)*2;
   int b=Character.digit(HEX.charAt(offset),16)*16+Character.digit(HEX.charAt(offset+1),16);
   if((b&(128>>(x%8)))!=0)p[(y+8)*212+xs[g]+x]=0xff000000;
  }
  for(int y=0;y<6;y++)for(int x=0;x<6;x++)if((2*x-5)*(2*x-5)+(2*y-5)*(2*y-5)<=36) {
   p[(34+y)*212+103+x]=0xff000000;p[(62+y)*212+103+x]=0xff000000;
  }
  return p;
 }
}
